'use client'

import { useEffect, useState, useCallback } from 'react'
import Image from 'next/image'
import type { Outfit } from '@/lib/types'
import { Button } from '@/components/ui/button'
import { Card } from '@/components/ui/card'
import { Skeleton } from '@/components/ui/skeleton'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from '@/components/ui/dialog'
import { FlatLayComposite } from './FlatLayComposite'
import { useFlatLayGeneration, useIntersectionObserver, cleanupExpiredCache } from '@/lib/hooks/useFlatLayGeneration'
import { useUserProfile } from '@/lib/hooks/useUserProfile'
import { generateTryOnLooks } from '@/lib/services/fitting-model-service'
import { Eye, Shirt, Heart, Share2, Loader2, RefreshCw, AlertCircle } from 'lucide-react'

interface SimilarOutfitsProps {
  outfits: Outfit[]
  onSelectOutfit: (outfit: Outfit) => void
}

interface SimilarOutfitCardProps {
  outfit: Outfit
  onSelect: (outfit: Outfit) => void
}

/**
 * Individual outfit card with lazy AI flat-lay generation
 */
function SimilarOutfitCard({ outfit, onSelect }: SimilarOutfitCardProps) {
  // Check if outfit already has a flat-lay image
  const existingFlatLay = outfit.flatLayImageUrl || outfit.flatLayImageBase64

  // Use flat-lay generation hook only when no existing image
  const {
    isGenerating,
    isQueued,
    flatLayImageBase64,
    error,
    generateFlatLay,
  } = useFlatLayGeneration({
    outfitId: outfit.id,
    items: outfit.items,
    occasionContext: outfit.title,
  })

  // Use intersection observer for lazy loading
  const observerRef = useIntersectionObserver(
    () => {
      // Only trigger generation if no existing flat-lay image
      if (!existingFlatLay && !flatLayImageBase64) {
        generateFlatLay()
      }
    },
    { threshold: 0.1 }
  )

  // Action button states
  const [isLiked, setIsLiked] = useState(false)
  const [showTryOnModal, setShowTryOnModal] = useState(false)
  const [isGeneratingTryOn, setIsGeneratingTryOn] = useState(false)
  const [tryOnImageUrl, setTryOnImageUrl] = useState<string | undefined>(outfit.tryOnImageUrl)
  const [tryOnImageBase64, setTryOnImageBase64] = useState<string | undefined>(outfit.tryOnImageBase64)
  const [tryOnError, setTryOnError] = useState<string | undefined>()

  // Get user profile for fitting model
  const { profile } = useUserProfile()
  const hasFittingModel = !!profile?.fittingModelUrl

  // Try-on image to display
  const tryOnImage = tryOnImageUrl || tryOnImageBase64

  // Sync with outfit prop when it changes
  useEffect(() => {
    if (outfit.tryOnImageUrl) {
      setTryOnImageUrl(outfit.tryOnImageUrl)
    }
    if (outfit.tryOnImageBase64) {
      setTryOnImageBase64(outfit.tryOnImageBase64)
    }
  }, [outfit.tryOnImageUrl, outfit.tryOnImageBase64])

  /**
   * Handle try-on button click
   */
  const handleTryOn = useCallback(async () => {
    // If we already have a try-on image, just open the modal
    if (tryOnImage) {
      setShowTryOnModal(true)
      return
    }

    // Check if user has a fitting model
    if (!hasFittingModel || !profile?.fittingModelUrl) {
      setTryOnError('กรุณาอัปโหลดรูปภาพในขั้นตอนการตั้งค่าเพื่อใช้ฟีเจอร์ลองใส่')
      setShowTryOnModal(true)
      return
    }

    // Start generation
    setIsGeneratingTryOn(true)
    setTryOnError(undefined)
    setShowTryOnModal(true)

    try {
      // Extract outfit items for the prompt
      const outfitItems = outfit.items.map(item => ({
        name: item.name,
        category: item.category || item.subCategory || 'clothing',
        color: item.colors?.[0],
      }))

      // Pass flat-lay image for dual reference mode (outfit consistency)
      const result = await generateTryOnLooks({
        fittingModelImageUrl: profile.fittingModelUrl,
        outfitItems,
        outfitTitle: outfit.title,
        flatLayImageUrl: outfit.flatLayImageUrl,
        flatLayImageBase64: outfit.flatLayImageBase64,
      })

      if (result.success) {
        setTryOnImageUrl(result.imageUrl)
        setTryOnImageBase64(result.imageBase64)
        setTryOnError(undefined)
      } else {
        setTryOnError(result.message || 'ไม่สามารถสร้างรูปภาพได้ กรุณาลองอีกครั้ง')
      }
    } catch (err) {
      console.error('[TryOn] Error:', err)
      setTryOnError('เกิดข้อผิดพลาด กรุณาลองอีกครั้ง')
    } finally {
      setIsGeneratingTryOn(false)
    }
  }, [tryOnImage, hasFittingModel, profile?.fittingModelUrl, outfit])

  /**
   * Handle regenerate try-on image
   */
  const handleRegenerate = useCallback(async () => {
    // Clear current image and regenerate
    setTryOnImageUrl(undefined)
    setTryOnImageBase64(undefined)
    setIsGeneratingTryOn(true)
    setTryOnError(undefined)

    if (!profile?.fittingModelUrl) {
      setTryOnError('กรุณาอัปโหลดรูปภาพในขั้นตอนการตั้งค่าเพื่อใช้ฟีเจอร์ลองใส่')
      setIsGeneratingTryOn(false)
      return
    }

    try {
      const outfitItems = outfit.items.map(item => ({
        name: item.name,
        category: item.category || item.subCategory || 'clothing',
        color: item.colors?.[0],
      }))

      // Pass flat-lay image for dual reference mode (outfit consistency)
      const result = await generateTryOnLooks({
        fittingModelImageUrl: profile.fittingModelUrl,
        outfitItems,
        outfitTitle: outfit.title,
        flatLayImageUrl: outfit.flatLayImageUrl,
        flatLayImageBase64: outfit.flatLayImageBase64,
      })

      if (result.success) {
        setTryOnImageUrl(result.imageUrl)
        setTryOnImageBase64(result.imageBase64)
        setTryOnError(undefined)
      } else {
        setTryOnError(result.message || 'ไม่สามารถสร้างรูปภาพได้ กรุณาลองอีกครั้ง')
      }
    } catch (err) {
      console.error('[TryOn] Regenerate error:', err)
      setTryOnError('เกิดข้อผิดพลาด กรุณาลองอีกครั้ง')
    } finally {
      setIsGeneratingTryOn(false)
    }
  }, [profile?.fittingModelUrl, outfit])

  // Determine which image to display
  const displayImage = existingFlatLay || flatLayImageBase64
  const showActiveLoading = isGenerating && !displayImage
  const showQueuedLoading = isQueued && !displayImage && !isGenerating
  const showFallback = !displayImage && !isGenerating && !isQueued && error
  // Show waiting state before intersection triggers (no cache, no error, not generating, not queued)
  const showWaitingState = !displayImage && !isGenerating && !isQueued && !error

  return (
    <>
      <Card
        className="relative cursor-pointer hover:shadow-md transition-shadow overflow-hidden active:scale-[0.98] transition-transform"
        onClick={() => onSelect(outfit)}
      >
        {/* Observer target - separate element that doesn't block clicks */}
        <span
          ref={observerRef}
          className="absolute inset-0 pointer-events-none"
          aria-hidden="true"
        />
        <div className="aspect-[3/4] bg-gray-100 relative">
          {showActiveLoading ? (
            // Active loading skeleton while flat-lay is generating
            <div className="relative w-full h-full">
              <Skeleton className="w-full h-full absolute inset-0" />
              <div className="absolute inset-0 flex flex-col items-center justify-center z-10">
                <div className="flex justify-center mb-2">
                  <div className="flex space-x-1">
                    <div className="w-2 h-2 bg-primary rounded-full animate-bounce" />
                    <div
                      className="w-2 h-2 bg-primary rounded-full animate-bounce"
                      style={{ animationDelay: '0.1s' }}
                    />
                    <div
                      className="w-2 h-2 bg-primary rounded-full animate-bounce"
                      style={{ animationDelay: '0.2s' }}
                    />
                  </div>
                </div>
                <p className="text-xs text-gray-500">กำลังสร้างภาพ...</p>
              </div>
            </div>
          ) : showQueuedLoading ? (
            // Queued state - shimmer animation while waiting in queue
            <div className="relative w-full h-full">
              <Skeleton className="w-full h-full absolute inset-0 animate-pulse" />
              <div className="absolute inset-0 flex flex-col items-center justify-center z-10">
                <div className="flex justify-center mb-2">
                  <div className="w-6 h-6 border-2 border-primary border-t-transparent rounded-full animate-spin" />
                </div>
                <p className="text-xs text-gray-500">รอคิว...</p>
              </div>
            </div>
          ) : showWaitingState ? (
            // Initial waiting state before intersection - show loading skeleton
            <div className="relative w-full h-full">
              <Skeleton className="w-full h-full absolute inset-0 animate-pulse" />
              <div className="absolute inset-0 flex flex-col items-center justify-center z-10">
                <p className="text-xs text-gray-400">รอดูภาพ...</p>
              </div>
            </div>
          ) : displayImage ? (
            // Show flat-lay image
            <Image
              src={displayImage}
              alt={outfit.title}
              fill
              className="object-contain"
              sizes="(max-width: 768px) 50vw, 200px"
              unoptimized={displayImage.startsWith('data:')}
            />
          ) : showFallback ? (
            // Fallback to CSS composite on error only
            <FlatLayComposite items={outfit.items} />
          ) : null}
        </div>

        <div className="p-2">
          <div className="space-y-0.5">
            <p className="text-xs font-medium line-clamp-1">{outfit.title}</p>
            <p className="text-xs text-muted-foreground">{outfit.items.length} ชิ้น</p>
            <p className="text-xs text-primary font-bold">
              ฿{outfit.totalPrice.toLocaleString()}
            </p>
          </div>

          {/* Action buttons row */}
          <div className="flex items-center gap-1 mt-1.5">
            <Button
              size="sm"
              variant="ghost"
              onClick={(e) => { e.stopPropagation(); onSelect(outfit); }}
              className="flex-1 h-7 text-xs gap-0.5 px-1"
            >
              <Eye className="w-3 h-3" />
              ดูลุค
            </Button>
            <Button
              size="sm"
              variant="ghost"
              onClick={(e) => { e.stopPropagation(); handleTryOn(); }}
              disabled={isGeneratingTryOn}
              className="h-7 px-1.5 text-xs gap-0.5"
              aria-label="ลองใส่ outfit นี้"
              title={hasFittingModel ? 'ลองใส่' : 'กรุณาอัปโหลดรูปภาพก่อน'}
            >
              {isGeneratingTryOn ? (
                <Loader2 className="w-3 h-3 animate-spin" />
              ) : (
                <Shirt className="w-3 h-3" />
              )}
              ลองใส่
            </Button>
            <Button
              size="sm"
              variant="ghost"
              onClick={(e) => { e.stopPropagation(); setIsLiked(!isLiked); }}
              className="h-7 w-7 p-0"
              aria-label={isLiked ? "Unlike outfit" : "Like outfit"}
            >
              <Heart className={`w-3.5 h-3.5 ${isLiked ? "fill-red-500 text-red-500" : "text-gray-600"}`} />
            </Button>
            <Button
              size="sm"
              variant="ghost"
              onClick={(e) => e.stopPropagation()}
              className="h-7 w-7 p-0"
              aria-label="Share outfit"
            >
              <Share2 className="w-3.5 h-3.5 text-gray-600" />
            </Button>
          </div>
        </div>
      </Card>

      {/* Try-On Modal */}
      <Dialog open={showTryOnModal} onOpenChange={setShowTryOnModal}>
        <DialogContent className="max-w-md mx-auto">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <Shirt className="w-5 h-5" />
              ลองใส่: {outfit.title}
            </DialogTitle>
            <DialogDescription>
              ดูชุดนี้บนโมเดลของคุณ
            </DialogDescription>
          </DialogHeader>

          {/* Try-On Image Area */}
          <div className="relative w-full aspect-[3/4] bg-gray-100 rounded-lg overflow-hidden">
            {isGeneratingTryOn ? (
              // Loading state
              <div className="absolute inset-0 flex flex-col items-center justify-center">
                <Skeleton className="w-full h-full absolute inset-0" />
                <div className="z-10 text-center px-4">
                  <div className="flex justify-center mb-3">
                    <Loader2 className="w-8 h-8 text-primary animate-spin" />
                  </div>
                  <p className="text-sm text-gray-600 font-medium">กำลังสร้างรูปภาพ...</p>
                  <p className="text-xs text-gray-400 mt-1">อาจใช้เวลา 10-30 วินาที</p>
                </div>
              </div>
            ) : tryOnError ? (
              // Error state
              <div className="absolute inset-0 flex flex-col items-center justify-center p-4">
                <div className="text-center">
                  <AlertCircle className="w-12 h-12 text-red-400 mx-auto mb-3" />
                  <p className="text-sm text-gray-600 mb-4">{tryOnError}</p>
                  {hasFittingModel && (
                    <Button
                      size="sm"
                      variant="outline"
                      onClick={handleRegenerate}
                      className="gap-2"
                    >
                      <RefreshCw className="w-4 h-4" />
                      ลองอีกครั้ง
                    </Button>
                  )}
                </div>
              </div>
            ) : tryOnImage ? (
              // Show try-on image
              <Image
                src={tryOnImage}
                alt={`ลองใส่: ${outfit.title}`}
                fill
                className="object-contain"
                sizes="(max-width: 768px) 100vw, 400px"
              />
            ) : (
              // Empty state (should not happen normally)
              <div className="w-full h-full flex items-center justify-center bg-gray-200">
                <span className="text-gray-400 text-sm">ไม่มีรูปภาพ</span>
              </div>
            )}
          </div>

          {/* Action buttons */}
          <div className="flex gap-2 mt-2">
            {tryOnImage && !isGeneratingTryOn && (
              <Button
                size="sm"
                variant="outline"
                onClick={handleRegenerate}
                className="flex-1 gap-2"
              >
                <RefreshCw className="w-4 h-4" />
                ลองใส่ใหม่
              </Button>
            )}
            <Button
              size="sm"
              variant="default"
              onClick={() => setShowTryOnModal(false)}
              className="flex-1"
            >
              ปิด
            </Button>
          </div>
        </DialogContent>
      </Dialog>
    </>
  )
}

/**
 * SimilarOutfits - Displays a grid of similar outfit recommendations
 * with lazy AI-generated flat-lay images
 */
export function SimilarOutfits({ outfits, onSelectOutfit }: SimilarOutfitsProps) {
  // Cleanup expired cache entries on mount
  useEffect(() => {
    cleanupExpiredCache()
  }, [])

  if (outfits.length === 0) return null

  return (
    <div className="mt-6 pb-4">
      <h3 className="font-medium mb-3">Similar outfits</h3>

      <div className="grid grid-cols-2 gap-3">
        {outfits.slice(0, 6).map((outfit) => (
          <SimilarOutfitCard
            key={outfit.id}
            outfit={outfit}
            onSelect={onSelectOutfit}
          />
        ))}
      </div>
    </div>
  )
}

'use client'

import type { Product } from '@/lib/types'

interface FlatLayCompositeProps {
  items: Product[]
}

interface CategorizedItems {
  mainItem: Product | null
  shoes: Product[]
  accessories: Product[]
}

/**
 * Categorizes outfit items into main garment, shoes, and accessories
 * Uses case-insensitive matching on category and subCategory fields
 */
function categorizeItems(items: Product[]): CategorizedItems {
  const mainCategories = ['dress', 'top', 'blouse', 'shirt', 'pants', 'skirt', 'jacket', 'blazer', 'coat', 'sweater', 'cardigan', 'jumpsuit', 'romper', 'suit', 'vest', 'tee', 't-shirt']
  const shoeCategories = ['shoes', 'shoe', 'footwear', 'heels', 'heel', 'sneakers', 'sneaker', 'sandals', 'sandal', 'boots', 'boot', 'loafers', 'loafer', 'flats', 'flat', 'pumps', 'pump', 'mules', 'mule', 'oxfords', 'oxford']

  let mainItem: Product | null = null
  const shoes: Product[] = []
  const accessories: Product[] = []

  for (const item of items) {
    const category = (item.category || '').toLowerCase()
    const subCategory = (item.subCategory || '').toLowerCase()
    const combined = `${category} ${subCategory}`

    const isShoe = shoeCategories.some(sc => combined.includes(sc))
    const isMain = mainCategories.some(mc => combined.includes(mc))

    if (isShoe) {
      shoes.push(item)
    } else if (isMain && !mainItem) {
      mainItem = item
    } else if (isMain) {
      // Additional main items become accessories
      accessories.push(item)
    } else {
      accessories.push(item)
    }
  }

  // If no main item found, use the first item with an image
  if (!mainItem && items.length > 0) {
    const itemWithImage = items.find(i => i.imageUrl)
    if (itemWithImage) {
      mainItem = itemWithImage
      // Remove from other arrays if it was placed there
      const shoeIdx = shoes.indexOf(itemWithImage)
      if (shoeIdx > -1) shoes.splice(shoeIdx, 1)
      const accIdx = accessories.indexOf(itemWithImage)
      if (accIdx > -1) accessories.splice(accIdx, 1)
    } else {
      mainItem = items[0]
    }
  }

  return { mainItem, shoes, accessories }
}

/**
 * FlatLayComposite - Creates a CSS-based flat-lay aesthetic composition of outfit items
 * Arranges items in an artistic flat-lay style using CSS transforms and absolute positioning
 */
export function FlatLayComposite({ items }: FlatLayCompositeProps) {
  if (!items || items.length === 0) {
    return (
      <div className="w-full h-full bg-white flex items-center justify-center">
        <span className="text-gray-400 text-xs">No items</span>
      </div>
    )
  }

  const { mainItem, shoes, accessories } = categorizeItems(items)

  // Single item - display centered
  if (items.length === 1 && mainItem) {
    return (
      <div className="w-full h-full bg-white relative overflow-hidden">
        <div className="absolute inset-0 flex items-center justify-center p-2">
          {mainItem.imageUrl ? (
            <img
              src={mainItem.imageUrl}
              alt={mainItem.name}
              className="max-w-full max-h-full object-contain drop-shadow-md"
            />
          ) : (
            <div className="w-full h-full bg-gray-100 flex items-center justify-center">
              <span className="text-gray-400 text-xs text-center px-2">{mainItem.name}</span>
            </div>
          )}
        </div>
      </div>
    )
  }

  // Get first shoe and first accessory for composition
  const shoe = shoes[0]
  const accessory = accessories[0]
  // Additional accessories for more complex compositions
  const secondAccessory = accessories[1]

  return (
    <div className="w-full h-full bg-white relative overflow-hidden">
      {/* Main item - large, center-left position */}
      {mainItem && mainItem.imageUrl && (
        <div
          className="absolute"
          style={{
            top: '8%',
            left: '15%',
            width: '70%',
            height: '75%',
            zIndex: 1,
            transform: 'rotate(-2deg)',
          }}
        >
          <img
            src={mainItem.imageUrl}
            alt={mainItem.name}
            className="w-full h-full object-contain drop-shadow-md"
          />
        </div>
      )}

      {/* Shoes - positioned at bottom-left with rotation */}
      {shoe && shoe.imageUrl && (
        <div
          className="absolute"
          style={{
            bottom: '5%',
            left: '3%',
            width: '38%',
            height: '35%',
            zIndex: 3,
            transform: 'rotate(-12deg)',
          }}
        >
          <img
            src={shoe.imageUrl}
            alt={shoe.name}
            className="w-full h-full object-contain drop-shadow-lg"
          />
        </div>
      )}

      {/* Primary accessory - positioned at top-right or bottom-right with rotation */}
      {accessory && accessory.imageUrl && (
        <div
          className="absolute"
          style={{
            top: '5%',
            right: '3%',
            width: '32%',
            height: '30%',
            zIndex: 2,
            transform: 'rotate(10deg)',
          }}
        >
          <img
            src={accessory.imageUrl}
            alt={accessory.name}
            className="w-full h-full object-contain drop-shadow-md"
          />
        </div>
      )}

      {/* Secondary accessory - positioned at bottom-right */}
      {secondAccessory && secondAccessory.imageUrl && (
        <div
          className="absolute"
          style={{
            bottom: '8%',
            right: '5%',
            width: '28%',
            height: '25%',
            zIndex: 4,
            transform: 'rotate(5deg)',
          }}
        >
          <img
            src={secondAccessory.imageUrl}
            alt={secondAccessory.name}
            className="w-full h-full object-contain drop-shadow-md"
          />
        </div>
      )}

      {/* Fallback for main item without image */}
      {mainItem && !mainItem.imageUrl && (
        <div
          className="absolute bg-gray-100 flex items-center justify-center rounded"
          style={{
            top: '10%',
            left: '10%',
            width: '65%',
            height: '70%',
            zIndex: 1,
          }}
        >
          <span className="text-gray-400 text-xs text-center px-2">{mainItem.name}</span>
        </div>
      )}
    </div>
  )
}

'use client'

import { useState, useCallback, useRef, useEffect } from 'react'
import type { Product } from '@/lib/types'
import type { FlatLayItem, ImageGenerationResponse } from '@/lib/types/image-types'
import {
  validateProductVisualConsistency,
  validateFlatLayThumbnailMatch,
  findVisuallyConsistentReplacement,
  findReplacementsForInconsistentProducts,
  type ProductVisualConsistency,
} from '@/lib/utils/product-visual-validator'

/**
 * Cache configuration for localStorage
 */
const CACHE_PREFIX = 'flat-lay-'
const CACHE_TTL_MS = 7 * 24 * 60 * 60 * 1000 // 7 days in milliseconds

/**
 * Maximum concurrent generations to prevent API overload
 * Increased from 2 to 3 for faster generation
 */
const MAX_CONCURRENT_GENERATIONS = 3
let currentGenerations = 0

/**
 * Global queue for pending generation requests
 * Module-scoped to persist across component re-renders
 */
interface QueuedRequest {
  id: string
  execute: () => void
}
const generationQueue: QueuedRequest[] = []

/**
 * Process the next item in the queue if a slot is available
 */
function processQueue(): void {
  if (currentGenerations >= MAX_CONCURRENT_GENERATIONS || generationQueue.length === 0) {
    return
  }

  const nextRequest = generationQueue.shift()
  if (nextRequest) {
    nextRequest.execute()
  }
}

/**
 * Remove a request from the queue by ID
 */
function removeFromQueue(id: string): void {
  const index = generationQueue.findIndex(req => req.id === id)
  if (index !== -1) {
    generationQueue.splice(index, 1)
  }
}

/**
 * Get queue position for a given ID (0 = not in queue, 1+ = position)
 */
function getQueuePosition(id: string): number {
  const index = generationQueue.findIndex(req => req.id === id)
  return index === -1 ? 0 : index + 1
}

interface CachedImage {
  imageBase64: string
  timestamp: number
}

interface UseFlatLayGenerationOptions {
  /** Outfit ID for caching */
  outfitId: string
  /** Products to generate flat-lay image from */
  items: Product[]
  /** Occasion context for the generation */
  occasionContext?: string
  /** Full product catalog for finding replacements (optional) */
  allProducts?: Product[]
  /** Callback when products are replaced for visual consistency */
  onProductsReplaced?: (replacements: Map<string, Product>, updatedProducts: Product[]) => void
}

interface UseFlatLayGenerationResult {
  /** Whether the image is currently being generated */
  isGenerating: boolean
  /** Whether the request is queued waiting for a slot */
  isQueued: boolean
  /** Position in the queue (0 = not queued, 1+ = position) */
  queuePosition: number
  /** Generated image as base64 data URL */
  flatLayImageBase64: string | undefined
  /** Error message if generation failed */
  error: string | undefined
  /** Trigger the flat-lay generation manually */
  generateFlatLay: () => void
  /** Whether the image was loaded from cache */
  isFromCache: boolean
  /** Map of original SKU to replacement product (for visual consistency fixes) */
  productReplacements: Map<string, Product>
  /** Products that were used for generation (with replacements applied) */
  effectiveProducts: Product[]
}

/**
 * Checks if cached image is still valid (not expired)
 */
function isCacheValid(cached: CachedImage): boolean {
  const now = Date.now()
  return now - cached.timestamp < CACHE_TTL_MS
}

/**
 * Gets cached flat-lay image from localStorage
 */
function getCachedImage(outfitId: string): string | null {
  if (typeof window === 'undefined') return null

  try {
    const key = `${CACHE_PREFIX}${outfitId}`
    const cached = localStorage.getItem(key)
    if (!cached) return null

    const parsed: CachedImage = JSON.parse(cached)
    if (isCacheValid(parsed)) {
      return parsed.imageBase64
    } else {
      // Remove expired cache
      localStorage.removeItem(key)
      return null
    }
  } catch (error) {
    console.warn('[useFlatLayGeneration] Error reading cache:', error)
    return null
  }
}

/**
 * Saves generated image to localStorage cache
 * Implements automatic cache eviction when quota is exceeded
 */
function setCachedImage(outfitId: string, imageBase64: string): void {
  if (typeof window === 'undefined') return

  const key = `${CACHE_PREFIX}${outfitId}`
  const cached: CachedImage = {
    imageBase64,
    timestamp: Date.now(),
  }
  const cacheValue = JSON.stringify(cached)

  // Maximum retry attempts with progressive eviction
  const maxRetries = 3
  const evictionCounts = [1, 2, Number.MAX_SAFE_INTEGER] // Evict 1, then 2, then all remaining

  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      localStorage.setItem(key, cacheValue)

      // Success - log if we had to evict entries
      if (attempt > 0) {
        console.log(`[useFlatLayGeneration] Successfully cached after evicting entries (attempt ${attempt + 1})`)
      }
      return
    } catch (error) {
      // Check if this is a QuotaExceededError
      const isQuotaError =
        error instanceof DOMException &&
        (error.name === 'QuotaExceededError' || error.name === 'NS_ERROR_DOM_QUOTA_REACHED')

      if (isQuotaError && attempt < maxRetries) {
        // Attempt cache eviction
        const entriesToEvict = evictionCounts[attempt]
        console.warn(
          `[useFlatLayGeneration] localStorage quota exceeded. ` +
          `Attempting to evict ${entriesToEvict === Number.MAX_SAFE_INTEGER ? 'all remaining' : entriesToEvict} entries...`
        )

        const evicted = evictOldestCacheEntries(entriesToEvict)
        console.log(`[useFlatLayGeneration] Evicted ${evicted} cache entries`)

        if (evicted === 0) {
          // No cache entries to evict, image might be too large
          console.warn(
            '[useFlatLayGeneration] No cache entries available to evict. ' +
            'Image may be too large for localStorage quota.'
          )
          return
        }

        // Continue to next retry attempt
        continue
      } else {
        // Non-quota error or all retries exhausted
        if (isQuotaError) {
          console.warn(
            '[useFlatLayGeneration] Failed to cache image after all eviction attempts. ' +
            'localStorage quota cannot accommodate this image.'
          )
        } else {
          console.warn('[useFlatLayGeneration] Error saving to cache:', error)
        }
        return
      }
    }
  }
}

/**
 * Cleans up expired cache entries
 * Call this periodically to prevent localStorage bloat
 */
export function cleanupExpiredCache(): void {
  if (typeof window === 'undefined') return

  try {
    const keys: string[] = []
    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i)
      if (key?.startsWith(CACHE_PREFIX)) {
        keys.push(key)
      }
    }

    for (const key of keys) {
      try {
        const cached = localStorage.getItem(key)
        if (cached) {
          const parsed: CachedImage = JSON.parse(cached)
          if (!isCacheValid(parsed)) {
            localStorage.removeItem(key)
          }
        }
      } catch {
        // Invalid cache entry, remove it
        localStorage.removeItem(key)
      }
    }
  } catch (error) {
    console.warn('[useFlatLayGeneration] Error cleaning cache:', error)
  }
}

/**
 * Evicts oldest cache entries to free up localStorage space
 * @param count Number of entries to evict (default 1)
 * @returns Number of entries actually evicted
 */
function evictOldestCacheEntries(count: number = 1): number {
  if (typeof window === 'undefined') return 0

  try {
    // Collect all flat-lay cache entries with their timestamps
    const cacheEntries: Array<{ key: string; timestamp: number }> = []

    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i)
      if (key?.startsWith(CACHE_PREFIX)) {
        try {
          const cached = localStorage.getItem(key)
          if (cached) {
            const parsed: CachedImage = JSON.parse(cached)
            cacheEntries.push({ key, timestamp: parsed.timestamp })
          }
        } catch {
          // Corrupted entry, add with timestamp 0 to prioritize removal
          cacheEntries.push({ key, timestamp: 0 })
        }
      }
    }

    if (cacheEntries.length === 0) {
      return 0
    }

    // Sort by timestamp (oldest first)
    cacheEntries.sort((a, b) => a.timestamp - b.timestamp)

    // Remove the specified number of oldest entries
    const toEvict = Math.min(count, cacheEntries.length)
    let evicted = 0

    for (let i = 0; i < toEvict; i++) {
      try {
        localStorage.removeItem(cacheEntries[i].key)
        evicted++
      } catch {
        // Failed to remove, continue with others
        console.warn(`[useFlatLayGeneration] Failed to evict cache entry: ${cacheEntries[i].key}`)
      }
    }

    return evicted
  } catch (error) {
    console.warn('[useFlatLayGeneration] Error during cache eviction:', error)
    return 0
  }
}

/**
 * Result of transforming products to flat-lay items with validation
 */
interface TransformResult {
  items: FlatLayItem[]
  validationIssues: Array<{ sku: string; name: string; issues: string[] }>
  hasInconsistentItems: boolean
  /** Map of original SKU to replacement product */
  replacements: Map<string, Product>
  /** SKUs of items that couldn't be replaced */
  excludedSkus: string[]
  /** Products after replacement (these products were used for FlatLayItems) */
  effectiveProducts: Product[]
}

/**
 * Transforms Product array to FlatLayItem array for API request
 * Includes visual consistency validation to detect mismatches between
 * product descriptions and product thumbnails
 *
 * When allProducts is provided and mismatches are detected, this function
 * attempts to find visually consistent replacement products.
 *
 * @param items - Products to transform
 * @param enableValidation - Whether to run visual consistency checks (default: true)
 * @param allProducts - Full product catalog for finding replacements (optional)
 */
function transformToFlatLayItems(
  items: Product[],
  enableValidation: boolean = true,
  allProducts?: Product[]
): TransformResult {
  const validationIssues: Array<{ sku: string; name: string; issues: string[] }> = []
  let hasInconsistentItems = false
  const replacements = new Map<string, Product>()
  const excludedSkus: string[] = []

  // First pass: identify inconsistent items and find replacements if catalog provided
  let effectiveProducts: Product[] = items

  if (enableValidation && allProducts && allProducts.length > 0) {
    // Use the batch replacement function for efficiency
    const replacementResult = findReplacementsForInconsistentProducts(
      items,
      allProducts,
      { targetGender: 'women' }
    )

    effectiveProducts = replacementResult.products
    hasInconsistentItems = replacementResult.inconsistentCount > 0

    // Copy replacements to our map
    replacementResult.replacements.forEach((replacement, originalSku) => {
      replacements.set(originalSku, replacement)
    })

    // Track unreplaceable items
    excludedSkus.push(...replacementResult.unreplaceableSkus)

    // Log replacements
    if (replacements.size > 0) {
      console.log(
        `[useFlatLayGeneration] Replaced ${replacements.size} visually inconsistent products:`,
        Array.from(replacements.entries()).map(([origSku, replacement]) => ({
          originalSku: origSku,
          replacementSku: replacement.sku,
          replacementName: replacement.name,
        }))
      )
    }

    if (excludedSkus.length > 0) {
      console.warn(
        `[useFlatLayGeneration] ${excludedSkus.length} items could not be replaced (will be included but may have visual mismatch):`,
        excludedSkus
      )
    }
  }

  // Transform products to FlatLayItems (using effective products which may include replacements)
  const flatLayItems = effectiveProducts.map((item, index) => {
    const originalItem = items[index]
    const wasReplaced = originalItem && replacements.has(originalItem.sku)

    // Run visual consistency validation on the effective item
    let isVisuallyConsistent = true
    if (enableValidation) {
      const validation = validateProductVisualConsistency(item, { enableLogging: false })
      const thumbnailMatch = validateFlatLayThumbnailMatch(item, { enableLogging: false })

      if (!validation.isConsistent || !thumbnailMatch.matches) {
        isVisuallyConsistent = false
        if (!wasReplaced) {
          // Only track as issue if this item wasn't already replaced
          hasInconsistentItems = true
          validationIssues.push({
            sku: item.sku,
            name: item.name,
            issues: [
              ...validation.issues,
              ...(thumbnailMatch.reason ? [thumbnailMatch.reason] : []),
            ],
          })

          console.warn(
            `[useFlatLayGeneration] Visual mismatch detected for product "${item.name}" (${item.sku}):`,
            {
              textGender: validation.textGender,
              imageGender: validation.imageGender,
              issues: validation.issues,
              recommendation: thumbnailMatch.recommendation,
            }
          )
        }
      } else if (wasReplaced) {
        // Replacement is visually consistent - success!
        isVisuallyConsistent = true
      }
    }

    return {
      name: item.name,
      category: item.subCategory || item.category || 'clothing',
      color: item.colors?.[0],
      visualDescription: item.visualDescription,
      sku: item.sku,
      thumbnailUrl: item.imageUrl,
      isVisuallyConsistent,
    }
  })

  // Log summary if there are remaining issues after replacement attempts
  if (hasInconsistentItems && validationIssues.length > 0) {
    console.warn(
      `[useFlatLayGeneration] ${validationIssues.length} of ${items.length} items still have visual inconsistencies after replacement attempts`,
      validationIssues
    )
  }

  return {
    items: flatLayItems,
    validationIssues,
    hasInconsistentItems,
    replacements,
    excludedSkus,
    effectiveProducts,
  }
}

/**
 * Custom hook for lazy flat-lay image generation with caching
 *
 * Features:
 * - Checks localStorage cache synchronously on initial render
 * - Supports lazy loading via Intersection Observer
 * - Uses global queue system to manage concurrent generations
 * - Provides loading states, queue status, and error handling
 * - Falls back gracefully on errors
 */
export function useFlatLayGeneration({
  outfitId,
  items,
  occasionContext,
  allProducts,
  onProductsReplaced,
}: UseFlatLayGenerationOptions): UseFlatLayGenerationResult {
  // Initialize state synchronously from cache to prevent flicker
  const [flatLayImageBase64, setFlatLayImageBase64] = useState<string | undefined>(() => {
    const cached = getCachedImage(outfitId)
    return cached || undefined
  })
  const [isFromCache, setIsFromCache] = useState<boolean>(() => {
    return !!getCachedImage(outfitId)
  })
  const [isGenerating, setIsGenerating] = useState(false)
  const [isQueued, setIsQueued] = useState(false)
  const [queuePosition, setQueuePosition] = useState(0)
  const [error, setError] = useState<string | undefined>(undefined)
  const [productReplacements, setProductReplacements] = useState<Map<string, Product>>(new Map())
  const [effectiveProducts, setEffectiveProducts] = useState<Product[]>(items)

  // Track if generation has been attempted for this outfit
  const hasAttemptedRef = useRef(false)
  // Track if component is mounted
  const isMountedRef = useRef(true)
  // Track the current outfitId for cleanup
  const currentOutfitIdRef = useRef(outfitId)

  // Reset state when outfitId changes
  useEffect(() => {
    if (currentOutfitIdRef.current !== outfitId) {
      // Remove old request from queue if exists
      removeFromQueue(currentOutfitIdRef.current)

      // Check new outfit's cache
      const cached = getCachedImage(outfitId)
      if (cached) {
        setFlatLayImageBase64(cached)
        setIsFromCache(true)
        hasAttemptedRef.current = true
      } else {
        setFlatLayImageBase64(undefined)
        setIsFromCache(false)
        hasAttemptedRef.current = false
      }

      setIsGenerating(false)
      setIsQueued(false)
      setQueuePosition(0)
      setError(undefined)
      currentOutfitIdRef.current = outfitId
    }
  }, [outfitId])

  // Update queue position periodically when queued
  useEffect(() => {
    if (!isQueued) return

    const interval = setInterval(() => {
      const pos = getQueuePosition(outfitId)
      if (isMountedRef.current) {
        setQueuePosition(pos)
        if (pos === 0) {
          // No longer in queue, stop checking
          setIsQueued(false)
        }
      }
    }, 500)

    return () => clearInterval(interval)
  }, [isQueued, outfitId])

  // Cleanup on unmount
  useEffect(() => {
    isMountedRef.current = true
    return () => {
      isMountedRef.current = false
      // Remove from queue on unmount
      removeFromQueue(outfitId)
    }
  }, [outfitId])

  /**
   * Internal function to perform the actual generation
   */
  const performGeneration = useCallback(async () => {
    if (!isMountedRef.current) return

    // Mark as generating, not queued
    setIsQueued(false)
    setQueuePosition(0)
    setIsGenerating(true)
    setError(undefined)
    hasAttemptedRef.current = true
    currentGenerations++

    // Transform products to flat-lay items with visual consistency validation
    // Pass allProducts to enable automatic replacement of inconsistent items
    const transformResult = transformToFlatLayItems(items, true, allProducts)

    // Update replacement state
    setProductReplacements(transformResult.replacements)
    setEffectiveProducts(transformResult.effectiveProducts)

    // Notify parent component of replacements if callback provided
    if (transformResult.replacements.size > 0 && onProductsReplaced) {
      onProductsReplaced(transformResult.replacements, transformResult.effectiveProducts)
    }

    // Log visual consistency warnings
    if (transformResult.hasInconsistentItems && transformResult.excludedSkus.length > 0) {
      console.warn(
        '[useFlatLayGeneration] Some visual consistency issues remain after replacement attempts. ' +
        'Flat-lay image may not perfectly match product thumbnails for these items:',
        transformResult.excludedSkus
      )
    }

    // Extract just the items for the API call
    const flatLayItems = transformResult.items

    // Retry logic with exponential backoff
    const maxRetries = 1
    let lastError: string | undefined

    for (let attempt = 0; attempt <= maxRetries; attempt++) {
      try {
        if (attempt > 0) {
          // Exponential backoff: 2^attempt * 1000ms
          const delay = Math.pow(2, attempt) * 1000
          await new Promise(resolve => setTimeout(resolve, delay))
        }

        const response = await fetch('/api/generate-image', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({
            generationType: 'flat-lay',
            flatLayItems,
            occasionContext,
          }),
        })

        const result: ImageGenerationResponse = await response.json()

        if (!isMountedRef.current) {
          currentGenerations--
          processQueue() // Allow next in queue to proceed
          return
        }

        if (result.success && result.imageBase64) {
          setFlatLayImageBase64(result.imageBase64)
          setIsFromCache(false)
          setError(undefined)
          // Cache the generated image
          setCachedImage(outfitId, result.imageBase64)
          currentGenerations--
          setIsGenerating(false)
          processQueue() // Process next in queue
          return
        } else {
          lastError = result.message || result.error || 'Generation failed'
        }
      } catch (err) {
        console.error('[useFlatLayGeneration] API error:', err)
        lastError = err instanceof Error ? err.message : 'Network error'
      }
    }

    // All retries failed
    if (isMountedRef.current) {
      setError(lastError)
      setIsGenerating(false)
    }
    currentGenerations--
    processQueue() // Process next in queue even on failure
  }, [outfitId, items, occasionContext, allProducts, onProductsReplaced])

  /**
   * Generate flat-lay image via API
   * Uses global queue for concurrency management
   */
  const generateFlatLay = useCallback(() => {
    // Skip if already attempted, generating, queued, or has image
    if (hasAttemptedRef.current || isGenerating || isQueued || flatLayImageBase64) {
      return
    }

    // Check cache again in case it was populated while not observing
    const cached = getCachedImage(outfitId)
    if (cached) {
      setFlatLayImageBase64(cached)
      setIsFromCache(true)
      hasAttemptedRef.current = true
      return
    }

    // Check concurrent generation limit
    if (currentGenerations >= MAX_CONCURRENT_GENERATIONS) {
      // Add to queue
      const queuedRequest: QueuedRequest = {
        id: outfitId,
        execute: performGeneration,
      }
      generationQueue.push(queuedRequest)
      setIsQueued(true)
      setQueuePosition(generationQueue.length)
      return
    }

    // Slot available, generate immediately
    performGeneration()
  }, [outfitId, isGenerating, isQueued, flatLayImageBase64, performGeneration])

  return {
    isGenerating,
    isQueued,
    queuePosition,
    flatLayImageBase64,
    error,
    generateFlatLay,
    isFromCache,
    productReplacements,
    effectiveProducts,
  }
}

/**
 * Hook for using Intersection Observer to trigger lazy generation
 */
export function useIntersectionObserver(
  callback: () => void,
  options?: IntersectionObserverInit
): React.RefCallback<HTMLElement> {
  const observerRef = useRef<IntersectionObserver | null>(null)
  const hasTriggeredRef = useRef(false)

  const setRef = useCallback(
    (element: HTMLElement | null) => {
      // Disconnect previous observer
      if (observerRef.current) {
        observerRef.current.disconnect()
        observerRef.current = null
      }

      // Skip if already triggered or no element
      if (hasTriggeredRef.current || !element) {
        return
      }

      observerRef.current = new IntersectionObserver(
        (entries) => {
          const [entry] = entries
          if (entry?.isIntersecting && !hasTriggeredRef.current) {
            hasTriggeredRef.current = true
            callback()
            // Disconnect after triggering
            observerRef.current?.disconnect()
          }
        },
        {
          threshold: 0.1, // Trigger when 10% visible
          ...options,
        }
      )

      observerRef.current.observe(element)
    },
    [callback, options]
  )

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      observerRef.current?.disconnect()
    }
  }, [])

  return setRef
}

