   828→   * @private
   829→   */
   830→  private parseImageResponse(data: any): { base64?: string; url?: string } {
   831→    // OpenRouter returns images as base64 data URLs in the 'images' array
   832→    // Format: { choices: [{ message: { content: "...", images: ["data:image/png;base64,..."] } }] }
   833→
   834→    try {
   835→      console.log('[ImageGen] Parsing response:', JSON.stringify(data).slice(0, 500));
   836→
   837→      if (data.choices && data.choices[0] && data.choices[0].message) {
   838→        const message = data.choices[0].message;
   839→
   840→        // Primary format: images array (OpenRouter standard)
   841→        if (message.images && Array.isArray(message.images) && message.images.length > 0) {
   842→          const imageData = message.images[0];
   843→          console.log('[ImageGen] Found image in images array, type:', typeof imageData);
   844→
   845→          // Images are returned as data URLs (data:image/png;base64,...)
   846→          if (typeof imageData === 'string' && imageData.startsWith('data:image')) {
   847→            return { base64: imageData };
   848→          }
   849→
   850→          // Or as object with nested structure: {"type":"image_url","image_url":{"url":"data:..."}}
   851→          if (typeof imageData === 'object') {
   852→            // Check for image_url.url format (OpenRouter Gemini format)
   853→            if (imageData.image_url?.url) {
   854→              console.log('[ImageGen] Found image in image_url.url format');
   855→              const url = imageData.image_url.url;
   856→              if (url.startsWith('data:image')) {
   857→                return { base64: url };
   858→              }
   859→              return { url };
   860→            }
   861→            // Check for b64_json format
   862→            if (imageData.b64_json) {
   863→              return { base64: `data:image/png;base64,${imageData.b64_json}` };
   864→            }
   865→            // Check for direct base64/url
   866→            if (imageData.base64) {
   867→              return { base64: imageData.base64.startsWith('data:') ? imageData.base64 : `data:image/png;base64,${imageData.base64}` };
   868→            }
   869→            if (imageData.url) {
   870→              return { url: imageData.url };
   871→            }
   872→          }
   873→        }
   874→
   875→        // Check content for embedded base64 or URLs
   876→        const content = message.content;
   877→        if (typeof content === 'string') {
   878→          // Check if content contains base64 image data
   879→          const base64Match = content.match(/data:image\/(png|jpeg|jpg|webp);base64,[A-Za-z0-9+/=]+/);
   880→          if (base64Match) {
   881→            console.log('[ImageGen] Found base64 image in content');
   882→            return { base64: base64Match[0] };
   883→          }
   884→
   885→          // Check for URL in content
   886→          const urlMatch = content.match(/(https?:\/\/[^\s<>"]+\.(png|jpg|jpeg|gif|webp))/i);
   887→          if (urlMatch) {
   888→            console.log('[ImageGen] Found URL in content');
   889→            return { url: urlMatch[0] };
   890→          }
   891→        }
   892→
   893→        // Check for structured image data (fallback)
   894→        if (message.image) {
   895→          console.log('[ImageGen] Found image in message.image');
   896→          return {
   897→            base64: message.image.base64 || (message.image.b64_json ? `data:image/png;base64,${message.image.b64_json}` : undefined),
   898→            url: message.image.url,
   899→          };
   900→        }
   901→      }
   902→
   903→      // Fallback: return empty (will need to handle in caller)
   904→      console.warn('[ImageGen] Could not parse image from response. Keys:', Object.keys(data));
   905→      if (data.choices?.[0]?.message) {
   906→        console.warn('[ImageGen] Message keys:', Object.keys(data.choices[0].message));
   907→      }
   908→      return {};
   909→    } catch (error) {
   910→      console.error('[ImageGen] Error parsing image response:', error);
   911→      return {};
   912→    }
   913→  }
   914→
   915→  /**
   916→   * Client-side rate limiting check
   917→   * Limits to approximately 10 requests per minute
   918→   *
   919→   * @private
   920→   */
   921→  private checkRateLimit(): boolean {
   922→    const now = Date.now();
   923→    const minuteAgo = now - 60000;
   924→
   925→    // Reset counter if a minute has passed
   926→    if (this.lastRequestTime < minuteAgo) {
   927→      this.requestCount = 0;
   928→    }
   929→
   930→    // Check if under limit
   931→    if (this.requestCount >= 10) {
   932→      return false;
   933→    }
   934→
   935→    // Update counters
   936→    this.requestCount++;
   937→    this.lastRequestTime = now;
   938→
   939→    return true;
   940→  }
   941→
   942→  /**
   943→   * Checks if error is non-retryable (auth, validation, etc.)
   944→   *
   945→   * @private
   946→   */
   947→  private isNonRetryableError(error: any): boolean {
   948→    if (!error) return false;
   949→
   950→    const errorMessage = error.message || error.toString();
   951→
   952→    // Don't retry authentication errors
   953→    if (errorMessage.includes('401') || errorMessage.includes('403')) {
   954→      return true;
   955→    }
   956→
   957→    // Don't retry validation errors
   958→    if (errorMessage.includes('400') || errorMessage.includes('INVALID')) {
   959→      return true;
   960→    }
   961→
   962→    // Don't retry rate limit errors (need to wait)
   963→    if (errorMessage.includes('429') || errorMessage.includes('RATE_LIMIT')) {
   964→      return true;
   965→    }
   966→
   967→    return false;
   968→  }
   969→
   970→  /**
   971→   * Sleep utility for retry delays
   972→   *
   973→   * @private
   974→   */
   975→  private sleep(ms: number): Promise<void> {
   976→    return new Promise((resolve) => setTimeout(resolve, ms));
   977→  }
   978→}
   979→
   980→/**
   981→ * Creates a new OpenRouter image client with API key from environment
   982→ *
   983→ * @returns OpenRouterImageClient instance or null if API key not available
   984→ *
   985→ * @example
   986→ * const client = createImageClient();
   987→ * if (client) {
   988→ *   const response = await client.generateOutfitImage(description);
   989→ * }
   990→ */
   991→export function createImageClient(): OpenRouterImageClient | null {
   992→  const apiKey = process.env.OPENROUTER_API_KEY;
   993→
   994→  if (!apiKey) {
   995→    console.warn('[ImageGen] OPENROUTER_API_KEY not found in environment');
   996→    return null;
